mapper.select:
SELECT c.id AS card_id, c.user_id AS user_id, u.name AS owner_name, u.role AS owner_role, linked_cp.id AS card_product_id, COALESCE(linked_cp.company, c.company) AS company, COALESCE(c.card_name, linked_cp.name) AS card_name, COALESCE(linked_cp.annual_fee, 0) AS annual_fee, linked_cp.image AS image, JSON_UNQUOTE(JSON_EXTRACT(linked_cp.benefit, '$')) AS benefit, linked_cp.`condition` AS condition_text, DATE_FORMAT(linked_cp.updated_at, '%Y-%m-%d %H:%i:%s') AS condition_checked_at FROM card c INNER JOIN `user` u ON u.id = c.user_id LEFT JOIN card_product linked_cp ON linked_cp.id = c.card_product_id WHERE c.user_id IN
#{userId}
ORDER BY c.user_id ASC, COALESCE(linked_cp.company, c.company) ASC, COALESCE(c.card_name, linked_cp.name) ASC, c.id ASC

SELECT c.id AS card_id, GREATEST( COALESCE(SUM( CASE WHEN cr.cancel_status IN ('1', '3') THEN 0 WHEN cr.cancel_status = '2' THEN cr.used_amount - COALESCE(cr.cancel_amount, 0) ELSE cr.used_amount END ), 0), 0 ) AS recognized_performance_amount FROM card c LEFT JOIN card_record cr ON cr.card_id = c.id AND cr.used_date >= #{startDate} AND cr.used_date <= #{endDate} WHERE c.id IN
#{cardId}
GROUP BY c.id

mapper.update:
UPDATE card
SET card_product_id = #{cardProductId}
WHERE id = #{cardId}
  AND card_product_id IS NULL
